import{z as l,x as p,o as t,c as B,q as r,j as o,D as E,d as A,s as n,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"存算分离","description":"","frontmatter":{"title":"存算分离","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/storage-compute-separation.md","filePath":"cs/storage-compute-separation.md","lastUpdated":1791063341000}'),d={name:"cs/storage-compute-separation.md"};function m(T,a,C,D,u,c){const s=p("Mermaid");return t(),B("div",null,[a[2]||(a[2]=r('<h1 id="存算分离" tabindex="-1">存算分离 <a class="header-anchor" href="#存算分离" aria-label="Permalink to &quot;存算分离&quot;">​</a></h1><div class="epigraph"><p>计算节点无本地权威盘，页与日志在共享存储服务上。弹性扩计算不必搬分片，代价是每次 miss 的网络 RTT 与多租户 QoS。</p><footer>—— 据云数据库拆分实践；共享磁盘谱系；缓冲池课的远程化</footer></div><p><a href="/cs/shared-nothing-vs-disk">上一课</a>把盘是否私有钉死。本课把「共享」升级为<strong>存储服务</strong>：对象存储或多租户页服务，计算无状态可杀。缺口不是再定义 WAL，而是缓冲、日志、延迟物化全部变成远程 I/O，校准与 2Q 策略要按 RTT 重做。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>本地 SSD 微秒；网络盘毫秒。缓冲池命中率从优化变成生存。缺口是 <strong>缓存层次</strong>：节点内存 → 本地盘缓存 → 远程权威。写：日志先写高耐久存储服务，数据页异步。与 TDE：密钥在计算侧或存储侧要合同。</p><p>弹性：只读副本无状态加计算，读己之写仍要粘滞或读带 LSN 的存储。分片可仍在，但再平衡可只改计算路由而不搬文件——文件在共享命名空间。</p><p><span class="marginnote">术语翻译：存算分离就是把「放数据的机器」和「跑查询的机器」拆开——计算节点像可随叫随到的临时工，说杀就杀、说加就加；数据本体住在共享存储服务里，谁当临时工都不影响账本在哪。</span></p><p><span class="marginnote">Aurora、Snowflake 一类是产品例子。本课机制：权威在存储，计算可丢。不把某云架构当唯一。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>页服务器：按页号读，写回带 LSN。计算宕机：另一计算从存储拉日志重放或已有页。compaction/vacuum 可在存储侧或计算作业。shuffle 尽量计算间，载荷尽量靠近存储做谓词下推（near-data）。</p><p>zone map 放存储侧，减少拉页——跳过索引课的远程版。</p>',11)),(t(),o(i,null,{default:E(()=>[n(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20COMP%5B%22%E6%97%A0%E7%8A%B6%E6%80%81%E8%AE%A1%E7%AE%97%22%5D%20--%3E%20CACHE%5B%22%E6%9C%AC%E5%9C%B0%E7%BC%93%E5%86%B2%22%5D%0A%20%20CACHE%20--%3E%20STOR%5B%22%E6%9D%83%E5%A8%81%E9%A1%B5%20%2F%20%E5%AF%B9%E8%B1%A1%E5%AD%98%E5%82%A8%22%5D%0A%20%20LOG%5B%22%E6%97%A5%E5%BF%97%E6%9C%8D%E5%8A%A1%22%5D%20--%3E%20STOR%0A%20%20COMP%20--%3E%20SCALE%5B%22%E5%8A%A0%E8%8A%82%E7%82%B9%E4%B8%8D%E6%90%AC%E6%9D%83%E5%A8%81%E6%95%B0%E6%8D%AE%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[A("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"组提交变成对日志服务的 gRPC fsync。RTO：存储健康则换计算快；存储挂则全体挂——故障域转移到存储集群。优化器必须用远程 I/O 权重，否则全选「扫描」以为像本地。",-1)),a[5]||(a[5]=e("p",null,"一次远程页读从计算节点发出到数据回来，中间每一跳都在付 RTT——这条链路决定了缓存层次为什么要重做。",-1)),(t(),o(i,null,{default:E(()=>[n(s,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20MISS%5B%22%E7%BC%93%E5%86%B2%E6%B1%A0%20miss%3A%20%E9%A1%B5%E4%B8%8D%E5%9C%A8%E8%8A%82%E7%82%B9%E5%86%85%E5%AD%98%22%5D%20--%3E%20LC%5B%22%E6%9F%A5%E6%9C%AC%E5%9C%B0%E7%9B%98%E7%BC%93%E5%AD%98%22%5D%0A%20%20LC%20--%20%22%E5%91%BD%E4%B8%AD%22%20--%3E%20RET%5B%22%E8%BF%94%E5%9B%9E%3A%20%E5%BE%AE%E7%A7%92%E7%BA%A7%22%5D%0A%20%20LC%20--%20%22miss%22%20--%3E%20NET%5B%22%E7%BD%91%E7%BB%9C%E8%AF%B7%E6%B1%82%E9%A1%B5%E6%9C%8D%E5%8A%A1%E5%99%A8%2F%E5%AF%B9%E8%B1%A1%E5%AD%98%E5%82%A8%3A%20%E6%AF%AB%E7%A7%92%E7%BA%A7%20RTT%22%5D%0A%20%20NET%20--%3E%20PUSH%5B%22%E5%AD%98%E5%82%A8%E4%BE%A7%E8%B0%93%E8%AF%8D%E4%B8%8B%E6%8E%A8%2Fzone%20map%20%E8%BF%87%E6%BB%A4%22%5D%0A%20%20PUSH%20--%3E%20RTN%5B%22%E5%8F%AA%E5%9B%9E%E6%9C%89%E7%94%A8%E9%A1%B5%E5%A1%AB%E5%85%A5%E6%9C%AC%E5%9C%B0%E7%BC%93%E5%AD%98%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>HTAP 下一课：同一存储两计算形态（行/列）或双引擎。</p><p><span class="marginnote">数字实例：本地 NVMe SSD 随机读约 \\(100\\ \\mu s\\)，跨可用区网络往返通常 \\(1\\text{–}2\\ ms\\)——同一页 miss 贵了约 \\(10\\) 到 \\(20\\) 倍。所以存算分离架构里，缓冲池命中率从 \\(99\\%\\) 掉到 \\(98\\%\\)，远程读次数会翻倍，这就是为什么缓存策略成了「生存问题」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不定义 HTAP。也不把存算分离当无 WAL。NewSQL 可分离也可无共享本地盘。</p><p>后课默认：云弹性常分离；代价是 RTT 与缓存设计。HTAP：同一数据服务 OLTP+OLAP。</p><p>没有本地权威盘，2Q 的「一次性扫描页」更应逐出，因为再填更贵。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>权威在存储服务，计算弹性；命中率与下推决定性能。</li><li>故障域转移到存储；日志仍先于页。</li><li>HTAP 下一课。</li><li>出处：共享磁盘谱系；云库实践；缓冲池课。</li></ul>',8))])}const S=l(d,[["render",m]]);export{f as __pageData,S as default};
